window.DECKS = window.DECKS || {};
window.DECKS.s3 = {
  polls: [
    { id: "s3-p20", q: "Your last sourcing event: when were the evaluation weights fixed?", options: ["Before issue, and disclosed to bidders", "Before issue, but not disclosed", "After the bids arrived", "There were no weights", "I don't know"] },
    { id: "s3-p21", q: "Nordvia P2 IT consulting (12 firms, 38 call-offs, no framework): which first event?", options: ["An e-auction on day rates", "A framework RFP with a rate card, then mini-competitions", "An RFQ for the cheapest firm", "A negotiation with Brightline only"] },
    { id: "s3-p22", q: "Which price scoring formula does your team use today?", options: ["Lowest price / bid price × 100", "Linear deviation from the lowest", "Ranking points (1st, 2nd, 3rd)", "No formula: judgement", "It changes every time"] },
    { id: "s3-p23", q: "Bidder C is about 20% below the average of the others and its hours look below the wage floor. Your first step?", options: ["Award it", "Exclude it at once", "Ask for a written explanation and check it against a should-cost model", "Tell the others to match it"] },
    { id: "s3-p24", q: "In Coupa, a Dutch reverse auction…", options: ["starts high and the price falls", "starts low and the price rises until a supplier accepts", "is the same as an English reverse auction", "is not available"] },
    { id: "s3-p25", q: "How many e-auctions has your team run in the last year?", options: ["None", "1 to 3", "4 to 10", "More than 10", "I don't know"] },
    { id: "s3-p26", q: "Which part of your RFx plan are you least sure about?", options: ["The event sequence", "The evaluation model", "Auction or not", "The Coupa set-up", "The regulatory gates"] }
  ],
  slides: [
    // ---------- Opening ----------
    { k: "title", h: "HOW do we run the event?", sub: "Session 3 · RFx, evaluation and e-auctions in Coupa" },
    { k: "statement", h: "The event cannot fix a wrong strategy. It can ruin a right one.", p: "Today we design and run the competitive event that delivers your route to market.", note: "Link back to Session 2: every participant now has a strategy paper. Today's rule is that nothing is designed until the route to market is stated." },
    { k: "steps", h: "Where we are in the course", s: [["WHAT are we sourcing?", "Done: need, category profile, power position"], ["WHICH route to market?", "Done: the sourcing strategy paper"], ["HOW do we run the event?", "Today: RFx plan, evaluation model, e-negotiation design"], ["HOW do we close it well?", "Next: negotiation, contract and handover"]], note: "Show where the Sourcing Case stands: parts 1 and 2 done, part 3 today, part 4 in Session 4, capstone four weeks later." },
    { k: "bullets", h: "Today you will", b: ["Choose the event sequence that follows from your strategy, and plan its timeline", "Build a weighted evaluation model, fixed before issue", "Evaluate real-looking bids fairly, including an abnormally low one", "Decide when an e-auction helps and when it hurts", "Write the Coupa set-up sheet for your own event"], note: "Five objectives, one per module. Each ends with a practice block in the workbook that becomes part of the Sourcing Case." },
    { k: "table", h: "Today's plan", t: [["Time", "Block"], ["0:00", "Fieldwork 2 debrief"], ["0:15", "3.1 The RFx toolbox"], ["0:45", "3.2 Designing the request"], ["1:25", "Break"], ["1:35", "3.3 Running it fairly"], ["2:15", "3.4 E-auctions"], ["2:50", "Break"], ["3:00", "3.5 Coupa Sourcing in practice"], ["3:30", "Case 3 and close"]], note: "Two breaks of ten minutes. The heavy calculation block (3.3) sits right after the first break, when energy is back." },
    { k: "section", n: "Debrief", h: "Fieldwork 2: the strategy paper", sub: "What changed when the business owner read your route to market?" },
    { k: "poll", poll: "s3-p1", note: "Use the result to pick two participants whose paper changed most; ask them to share in the plenary." },
    { k: "exercise", h: "Trio debrief", min: 10, where: "Breakout rooms", b: ["Each person: two minutes on the business owner conversation", "Which of the six strategy decisions did they challenge?", "Did Risk or Compliance add a gate (DORA, outsourcing)?", "One sentence for the plenary: what will your event now look like?"], note: "Keep strictly to time. The purpose is to bring the strategy back to mind before designing the event." },
    { k: "cards", h: "What business owners usually push back on", c: [["The number of suppliers", "‘Why only one?’ or ‘Why a panel, I know who I want’"], ["The term", "Too long for them, too short for the supplier's mobilisation"], ["The incumbent", "Fear of losing a supplier who knows the building or the systems"], ["The timeline", "They discover the notice deadline is closer than they thought"]], note: "Each push-back has a design answer today: lots and award rules, term options, a fair evaluation model, a backwards timeline." },

    // ---------- 3.1 ----------
    { k: "section", n: "3.1", h: "The RFx toolbox", sub: "Every tool answers a different question. Choose the question first." },
    { k: "statement", h: "The tool follows the strategy, never the reverse.", p: "‘We always do an RFQ with three quotes’ is a habit, not a strategy.", note: "Nordvia ran about 60 events a year, mostly three-quote RFQs whatever the category. Ask the room whether that sounds familiar." },
    { k: "cards", h: "Four tools, four questions", c: [["RFI", "Who can do this, and how? Market discovery and pre-qualification"], ["RFP", "What would you do, and at what price? Solution plus price"], ["RFQ", "What is your price for this exact thing? Price for a defined requirement"], ["E-auction", "How low will you go, live? Price discovery under rules"]], note: "These are Coupa's own distinctions: an RFI collects qualitative information, an RFQ prices items and lots, an RFP collects prices and information in the same event." },
    { k: "table", h: "RFI, RFP, RFQ: when and when not", t: [["Tool", "Use when", "Do not use when"], ["RFI", "New or changing market; before a framework; to build a BATNA", "The market is well known: it just adds weeks"], ["RFP", "Quality differs: soft FM, consulting, agencies, IT services, SaaS", "Pure commodities; sole source"], ["RFQ", "Standard items, unchanged renewals, pre-bid before an auction", "The specification is unclear"]], note: "Stress the RFI pitfalls: too long, prices treated as binding, used as free consulting. Suppliers remember." },
    { k: "cards", h: "Combined and multi-stage events", c: [["RFx + auction", "Coupa runs the RFx as the pre-bidding phase of an auction"], ["Multi-stage", "RFI → RFP → shortlist → dialogue → revised offers"], ["Follow-on events", "In Coupa, responses carry over to the next event as drafts"], ["BAFO", "A final sealed improvement from the shortlist, against the published criteria"]], note: "Multi-stage borrows the structure of the EU competitive procedure with negotiation (Directive 2014/24 Arts. 29–30) without its legal constraints." },
    { k: "flow", h: "A typical multi-stage pattern for complex services", s: ["RFI: pre-qualify", "RFP stage 1", "Shortlist of 3–4", "Dialogue workshops", "BAFO", "Award"], p: "An auction on price may follow BAFO only among bidders above the quality threshold, and only if the 3.4 preconditions hold.", note: "Use this for managed services and BPO, like Nordvia's Northbyte claims IT service. Never for a stationery catalogue." },
    { k: "table", h: "From route to market to event sequence", t: [["Route (Session 2)", "Event sequence"], ["One supplier by tender (cleaning, security)", "RFI optional → RFP → site visits → negotiation or BAFO"], ["Panel (consulting, IT services, agencies)", "Framework RFP with rate card → mini-competitions"], ["Sole or single source (incumbent software)", "Usage analysis → benchmark → RFI to alternatives → negotiation"], ["Commodity (office supplies, print)", "RFQ → English reverse auction → catalogue"], ["Strategic partnership", "RFI → RFP → dialogue → BAFO"]], note: "This is the bridge from Session 2. Ask each participant to find their own row before moving on." },
    { k: "example", h: "Nordvia P1 cleaning: the event sequence", tag: "Worked example (fictional)", b: ["Route: one supplier per lot, chosen by tender, 3 + 1 + 1 years", "No RFI: the local market is known; four to six capable cleaners", "RFP with hybrid specification, staff data and draft contract", "Site visits, clarification, then negotiation or BAFO with the best two", "Award, three months of mobilisation, start before the Jun 2027 expiry"], note: "Point out what is missing: no auction. Module 3.4 explains why." },
    { k: "example", h: "Nordvia P2 IT consulting: a panel, not a tender per project", tag: "Worked example (fictional)", b: ["Today: 12 firms, 38 call-offs, senior day rates from 820 to 1,450 euros", "Event 1: framework RFP by lot with a rate card of maximum day rates", "Award to three to five firms per lot", "Then: mini-competitions in Coupa RFP events above a threshold, documented direct award below it", "Labour law and DORA screened in the framework, not in every call-off"], note: "The framework event happens once; mini-competitions happen many times. Design both before issuing the first." },
    { k: "example", h: "Nordvia P3 Kelvar: no RFP for show", tag: "Worked example (fictional)", b: ["One vendor, €11.2M, 9% uplift last time, auto-renewal, 9 months' notice", "Two credible alternatives, but 18–24 months to migrate", "Event: an RFI to the two alternatives, to make the BATNA real", "Then: usage audit (20–25% shelfware estimated), benchmark, negotiation rounds", "Never an auction: there is one realistic supplier"], note: "An RFP that everyone knows will not change the supplier destroys credibility with the vendor and with the market. Session 4 runs the Kelvar negotiation." },
    { k: "poll", poll: "s3-p21", note: "Expected answer: the framework RFP with a rate card. An auction on day rates would buy cheap profiles, not capability." },
    { k: "table", h: "Indicative durations (rules of thumb)", t: [["Stage", "Indicative duration"], ["RFI response window", "2–3 weeks (practice)"], ["RFP response window, services", "3–6 weeks (illustrative)"], ["Simple mini-competition", "At least 10 working days (UK CCS reference)"], ["Evaluation and consensus", "2–4 weeks (illustrative)"], ["Negotiation, BAFO, approvals", "2–6 weeks (illustrative)"], ["Mobilisation, labour-intensive service", "Often around 3 months (illustrative)"]], foot: "Rules of thumb from practice, not norms. Replace them with your team's own data.", note: "Only the CCS 10-working-day minimum is a documented reference. Everything else is practice: say so." },
    { k: "flow", h: "Plan backwards from the notice deadline", s: ["Notice deadline", "Contract signed", "Award approved", "Evaluation and negotiation", "Bids received", "RFx issued", "Pack and weights agreed"], p: "Kelvar: with 9 months' notice on a Jun 2027 renewal, the real deadline is nine months before the expiry, not the expiry itself.", note: "Most ‘urgent’ events were missed notice dates. Ask participants to write their own notice date now." },
    { k: "cards", h: "What goes in every RFx pack", c: [["Instructions", "Timetable, rules, Q&A channel, how bids are evaluated"], ["Specification", "Input, output or hybrid; volumes and sites"], ["Pricing schedule", "One template for all; recurring, one-off and unit rates separated"], ["Questionnaire", "Knock-out questions first, then the scored ones"], ["Draft contract", "With SLAs, KPIs and service credits"], ["Regulatory annexes", "DORA Art. 30, outsourcing Art. 274 terms, data protection, staff data"]], note: "Six blocks. The two most often missing are the draft contract and the regulatory annex." },
    { k: "statement", h: "Attach the draft contract.", p: "With the contract in the pack, suppliers bid on your terms. Without it, you negotiate the terms after award, when your leverage has gone.", note: "Deviations from the draft contract become part of the evaluation. That is negotiation through bids rather than after award." },
    { k: "exercise", h: "Event sequence and timeline for your project", min: 15, where: "Practice 3.1 in your workbook", b: ["State your route to market from the strategy paper", "Write the notice deadline, not the expiry", "List the stages and the tool for each", "Plan start and duration backwards", "Tick what your RFx pack will contain"], note: "Walk the rooms. The most common error is a sequence that starts from today rather than from the notice deadline." },
    { k: "debrief", h: "Debrief", b: ["Whose sequence starts later than it should, and what will you do about it?", "Who removed an RFI, and who added one? Why?", "Who has a sole-source project: what is your RFI for?", "What will your draft contract need that it does not have today?"], note: "Collect two timelines on screen. Praise the backward plan, not the long one." },
    { k: "takeaways", h: "3.1 in three lines", b: ["Choose the question, then the tool: RFI, RFP, RFQ, BAFO or auction", "The sequence follows the route to market; sole source gets a negotiation, not an RFP for show", "Plan backwards from the notice deadline and attach the draft contract"], note: "Ask one participant to say the three lines in their own words before moving to 3.2." },

    // ---------- 3.2 ----------
    { k: "section", n: "3.2", h: "Designing the request", sub: "The request decides what you can compare, and therefore what you can award." },
    { k: "statement", h: "Decisions made early lock in most of the cost and risk.", p: "Van Weele's lesson: mistakes in the specification cannot be fixed in the evaluation.", note: "Van Weele & Rozemeijer, Procurement and Supply Chain Management, 8th ed. The point is the process model: specification comes first and weighs most." },
    { k: "two", h: "Input or output specification?", l: { t: "Input", b: ["Frequencies, hours, headcount, methods", "Easy to audit and compare", "Stifles innovation", "Often produces higher bids"] }, r: { t: "Output", b: ["Results: clean, safe, available, on time", "Suppliers propose the method, possibly cheaper", "Harder to draft and to assess", "Needs inspection and KPIs"] }, note: "CMS (2000) on FM contracts: both have merits, and a hybrid is the usual answer: outputs for most areas, prescribed methods where the insurer needs control (security procedures, data handling). Singapore's outcome-based cleaning guide shows how to specify results with inspection templates." },
    { k: "cards", h: "Lots: design them the way you will award", c: [["Coupa rule", "Items in a lot are always awarded together and ranked together"], ["By site or country", "Local suppliers can bid; mobilisation risk spread"], ["By service", "Cleaning separate from security, or combined soft FM"], ["Bundles", "Let suppliers price combinations: a discount or Sourcing Optimization"]], note: "A lot is a commercial decision. If you will never award it to one supplier, it should not be one lot." },
    { k: "example", h: "Nordvia P1 cleaning: the lot design", tag: "Worked example (fictional)", b: ["Lot 1: HQ (the site with quality complaints)", "Lot 2: second site in Country 1", "Lot 3: site in Country 2", "Bidders may bid for one, two or all lots, with an optional bundle discount", "Award rule published: best score per lot, bundles accepted only if cheaper in total"], note: "Countries are anonymised. The bundle rule is where Sourcing Optimization would help with more sites." },
    { k: "cards", h: "A pricing schedule that makes bids comparable", c: [["One template", "Your volumes, sites and assumptions filled in for everyone"], ["Three blocks", "Recurring price, one-off costs (mobilisation), unit rates for extras"], ["Indexation", "The mechanism is part of the bid, e.g. a wage index for cleaning"], ["No free text", "Prices in cells, conditions in the questionnaire"]], note: "If two bids cannot be put in the same spreadsheet without your interpretation, the schedule failed." },
    { k: "table", h: "TCO in evaluation (Ellram)", t: [["Cost type", "Indirect example"], ["Pre-transaction", "Tender effort, due diligence, onboarding in Coupa SIM"], ["Transaction", "Annual price, indexation, unit rates for extras"], ["Post-transaction", "Mobilisation, staff transfer, contract management FTE, exit and migration"]], note: "Ellram's TCO framework. For a cleaning switch, transition cost is real; for SaaS, exit and migration are often the largest hidden item." },
    { k: "two", h: "Knock-out criteria and weighted criteria", l: { t: "Knock-out (pass/fail)", b: ["Licences and vetting (security)", "Collective-wage compliance declaration (cleaning)", "ISO 27001 or equivalent (ICT)", "Acceptance of audit and access rights (DORA Art. 30, Art. 274)", "Financial standing"] }, r: { t: "Weighted (differentiating)", b: ["Service plan and staffing model", "KPIs, reporting and quality control", "Transition and mobilisation", "ESG and innovation", "Price or TCO"] }, hi: "r", note: "Regulatory requirements are gates, not points: a bidder who refuses supervisor access cannot win on price." },
    { k: "steps", h: "Building the evaluation model", s: [["Criteria", "From the specification and the strategy objectives"], ["Weights", "Quality vs price first, then sub-criteria"], ["Scale", "0–5 with written descriptors"], ["Evidence", "What each criterion asks bidders to show"], ["Formula", "How price becomes a score"], ["Fix and disclose", "Before issue, in the Coupa event"]], note: "Weights set after bids arrive are an equal-treatment and governance failure. The order on this slide is the order of work." },
    { k: "poll", poll: "s3-p20", note: "If most answers are not the first option, stop and ask why. This is the single most important governance rule of the session." },
    { k: "table", h: "A scoring scale with descriptors", t: [["Score", "Descriptor"], ["5", "Excellent: fully meets with evidence, adds value"], ["4", "Good: fully meets with evidence"], ["3", "Acceptable: meets, minor gaps"], ["2", "Weak: significant gaps"], ["1", "Poor: barely addresses it"], ["0", "Not met or no answer"]], note: "Descriptors make individual scores comparable before the consensus meeting. Without them, evaluators score their mood." },
    { k: "table", h: "Weights: reference points", t: [["Context", "Quality / price"], ["UK CCS consultancy further competitions", "Quality at least 50% (50–90%)"], ["UK university cleaning tender, 2024", "50 / 50"], ["Quality-led services (practice)", "50–70 / 30–50"], ["Well-specified commodity", "Price or a TCO formula decides"]], note: "The CCS and university examples are documented public references. The 50–70% range is common practice, not a norm." },
    { k: "poll", poll: "s3-p22", note: "Most teams use the first formula without knowing its side effect. The next slides show it." },
    { k: "two", h: "Two price scoring formulas", l: { t: "Relative to lowest", b: ["Score = lowest / bid × 100", "Simple and common", "Every score moves when the lowest bid changes", "One very low bid compresses the others"] }, r: { t: "Linear deviation", b: ["Score = 100 × (1 − (bid − lowest) / lowest)", "Floor at 0", "Punishes price gaps harder", "Favours cheaper bids more strongly"] }, note: "Neither is right or wrong. What is wrong is not knowing what your formula does before you publish it." },
    { k: "example", h: "The formula decides: Nordvia cleaning, 50/50", tag: "Worked example (fictional)", b: ["Relative formula, all bids: D 80.2, B 79.6, C 79.0", "Linear formula, all bids: C 79.0, B 78.3, D 77.5", "Same bids, same weights, a different winner", "Without C, relative: D 87.1, B 87.0; linear: B 87.0, D 86.8", "Lesson: test the formula on fictional bid sets before issue"], note: "These numbers come from the case in 3.3. Show this before the evaluation so participants see the formula as a design choice." },
    { k: "cards", h: "Common design mistakes", c: [["Gold-plated specification", "Asking for more than the business needs, and paying for it"], ["Weights after opening", "Changing the model to fit the preferred bidder"], ["First-year price only", "Ignoring indexation, mobilisation and exit"], ["Regulation as points", "Scoring audit rights instead of requiring them"]], note: "Each of these is a reason an award can be challenged by a losing bidder or questioned by Internal Audit." },
    { k: "exercise", h: "Your weighted evaluation model", min: 20, where: "Practice 3.2 in your workbook", b: ["Choose the specification type and the lots", "Set quality vs price, then the quality sub-criteria", "Write the knock-out criteria, including regulatory gates", "Choose the price formula", "List the TCO elements beyond the annual price"], note: "Ask participants to state whether sub-criterion weights are shares of 100 or shares of the quality weight. Either works if it is explicit." },
    { k: "debrief", h: "Debrief", b: ["Who has a knock-out criterion that is really a weighted one, or the reverse?", "Whose quality weight is below 50% for a service? Why?", "Which TCO element would change your ranking?", "Would your business owner sign these weights today?"], note: "The last question is the bridge to Fieldwork 3: the weights must be validated before issue." },
    { k: "takeaways", h: "3.2 in three lines", b: ["Specification and lots decide what you can compare and award", "Knock-outs for gates, weights for differences, TCO over the term", "Fix, test and disclose the model and the formula before issue"], note: "Bridge to 3.3: now we use a model on real-looking bids." },

    // ---------- 3.3 ----------
    { k: "section", n: "3.3", h: "Running it fairly", sub: "Q&A, evaluation and the award decision" },
    { k: "statement", h: "Fairness is what keeps good suppliers bidding next time.", p: "And what lets you defend the award to an auditor, a supervisor or a losing incumbent.", note: "Equal treatment is a legal duty in public procurement and a commercial asset in private procurement: suppliers price the risk of an unfair buyer." },
    { k: "cards", h: "Equal treatment in practice", c: [["Same information", "Same documents, same time, same deadline for all"], ["One channel", "All questions through the Coupa Message Center"], ["Shared answers", "Answers that matter to all are sent to all, anonymised"], ["No side channels", "Above all with the incumbent; brief stakeholders before issue"]], note: "Clarifications explain a bid; they do not let a bidder change it. Every Message Center exchange is logged and sends email notifications: that log is your equal-treatment evidence. The most common breach is the incumbent calling the business owner directly; brief the owner before issue." },
    { k: "steps", h: "The evaluation process", s: [["Compliance check", "Completeness and knock-out criteria"], ["Individual scoring", "About three evaluators, without seeing prices"], ["Consensus meeting", "Discuss gaps, agree one score with a rationale"], ["Commercial evaluation", "Published formula, TCO basis"], ["Sensitivity test", "Would reasonable changes alter the winner?"], ["Report", "Evaluation report and award recommendation"]], note: "Individual scoring by about three evaluators followed by consensus is the UK CCS consultancy guidance, and good private-sector practice too. Evaluators declare conflicts first. Whether Coupa has a formal sealed-envelope setting is not confirmed publicly: confirm in your tenant, or keep prices apart by role." },
    { k: "table", h: "Nordvia HQ cleaning: the four bids", t: [["Bidder", "Annual price €K", "Quality 0–100", "Note"], ["A (incumbent)", "690", "62", "Same method as today; staff continuity"], ["B", "610", "74", "Output-based plan, robot floor care at night"], ["C", "520", "58", "Hours look below the wage floor"], ["D", "655", "81", "Strongest quality and ESG; requires 4-year term"]], foot: "Fictional bids. Quality after consensus of three evaluators. Published model: 50/50.", note: "Ask the room to guess the winner before any calculation. Write the guesses down; we come back to them." },
    { k: "example", h: "Step 1: price scores", tag: "Worked example (fictional)", b: ["Formula: price score = lowest price / bid price × 100", "Lowest price: 520 (Bidder C)", "A: 520 / 690 × 100 = 75.4", "B: 520 / 610 × 100 = 85.2", "C: 100.0 · D: 520 / 655 × 100 = 79.4"], note: "Do the first one together on screen, then let the room compute the others." },
    { k: "bars", h: "Step 2: total scores at 50/50", d: [["D", 80.2, "80.2"], ["B", 79.6, "79.6"], ["C", 79.0, "79.0"], ["A", 68.7, "68.7"]], note: "Total = 0.5 × quality + 0.5 × price score. D, B and C are within 1.2 points. That is not a clear winner." },
    { k: "cards", h: "Abnormally low bids", c: [["The signal", "Far below the others or below a should-cost model"], ["The duty", "Ask the bidder in writing to explain, as CCS guidance does"], ["The test", "Hours × collective wage + on-costs + supervision + consumables + overhead + margin"], ["The decision", "Accept with evidence, or reject and record why"]], note: "Never reject automatically and never award blindly. A cleaning or security bid below the wage floor is a service-failure and legal risk." },
    { k: "example", h: "Bidder C under the microscope", tag: "Worked example (fictional)", b: ["Price 520: about 15% below the next bid, about 20% below the average of the others", "Quality 58: the weakest plan", "Staffing hours look below what the wage floor allows for the area", "Action: written request to explain hours, wage rates and supervision", "If the explanation fails: reject as abnormally low, record the evidence"], note: "The data note says ‘18% below the others’. Depending on the comparison it is 15% (next bid) or 20% (average). Either way it is a red flag." },
    { k: "table", h: "Step 3: sensitivity", t: [["Scenario", "D", "B", "C", "A"], ["50/50, all bids", "80.2", "79.6", "79.0", "68.7"], ["60/40, all bids", "80.4", "78.5", "74.8", "67.3"], ["40/60, all bids", "80.0", "80.7", "83.2", "70.0"], ["50/50, without C", "87.1", "87.0", "–", "75.2"], ["60/40, without C", "85.9", "84.4", "–", "72.6"]], foot: "Fictional. Relative price formula. Without C the lowest price becomes 610.", note: "At 40/60 the doubtful bid wins. At 60/40 D leads more clearly. Without C, D and B are almost tied at 50/50." },
    { k: "two", h: "What the sensitivity test tells you", l: { t: "It does not tell you", b: ["To change the weights now", "That the highest number wins regardless", "That C should be ignored silently"] }, r: { t: "It tells you", b: ["The decision is close between B and D", "C must be resolved first: it moves every price score", "Clarify, then negotiate or BAFO with B and D", "Say in the report that the result is sensitive"] }, hi: "r", note: "The weights were published at 50/50 and stay there. Sensitivity informs the next step; it never rewrites the model." },
    { k: "poll", poll: "s3-p23", note: "Expected: a written explanation checked against a should-cost model. Discuss why immediate exclusion is also risky." },
    { k: "cards", h: "Due diligence before award", c: [["Financial", "Standing, dependency on our contract, insurance cover"], ["Information security", "ISO 27001 or SOC 2, access control, data location"], ["Labour and ESG", "Wage compliance, subcontractors, code of conduct"], ["References", "Similar sites or services, checked by phone"]], note: "Due diligence runs on the preferred bidders, before award, as gates. It is not a weighted criterion." },
    { k: "table", h: "Regulatory gates for an insurer", t: [["If the service is…", "Gate before award"], ["An ICT service (DORA)", "Art. 28(4) pre-contract assessment: critical function? risks incl. concentration, due diligence, conflicts"], ["Supporting a critical or important function", "Art. 30(3) clauses accepted; exit strategy feasible; supervisor informed in time"], ["Outsourcing of a critical or important function (Solvency II)", "Art. 274: detailed examination of ability, capacity, authorisation; written agreement terms"], ["Processing personal data", "Data processing agreement and security review"]], note: "Most soft-FM categories are usually not critical outsourcing; Telmo and Northbyte may well be. The assessment is the insurer's own, documented." },
    { k: "cards", h: "The evaluation report", c: [["Process", "Who evaluated, conflicts declared, timeline, clarifications"], ["Results", "Scores per criterion with rationale, price scores, totals"], ["Tests", "Sensitivity, abnormally low bid handling, due diligence"], ["Recommendation", "Next step or award, conditions, risks, approvals needed"]], note: "Write it as if a losing bidder will ask for a debrief, because one will. Session 4 covers the award and the debriefing." },
    { k: "exercise", h: "Evaluate the Nordvia cleaning bids", min: 20, where: "Practice 3.3 in your workbook", b: ["Compute the price scores with lowest / bid × 100", "Compute the totals at 50/50 and at 60/40", "Recompute without Bidder C", "Name the abnormally low bid and what you will ask", "Write what the sensitivity tells you"], note: "The workbook checks the numbers automatically. Rooms that finish early compute the linear formula as a bonus." },
    { k: "debrief", h: "Debrief", b: ["Who guessed D at the start? Who guessed C?", "How did excluding C change the gap between B and D?", "Would you tell the business owner who is ‘winning’ at this stage?", "What would you put in the evaluation report about sensitivity?"], note: "Go back to the room's initial guesses. The point: intuition and model often differ, and the model must be defensible." },
    { k: "takeaways", h: "3.3 in three lines", b: ["Same information, one channel, no side doors: fairness is designed", "Score individually, agree by consensus, keep prices apart", "Resolve abnormally low bids and test sensitivity before you recommend"], note: "Bridge to 3.4: would an auction help us between B and D?" },

    // ---------- 3.4 ----------
    { k: "section", n: "3.4", h: "E-auctions: when they work and when they hurt", sub: "A sharp tool for well-specified leverage categories, a blunt one everywhere else." },
    { k: "statement", h: "An e-auction automates distributive bargaining.", p: "Real-time feedback replaces haggling. That is its strength, and its limit.", note: "Walton & McKersie's distributive bargaining: a fixed pie. Auctions do this well; they do not create value through multi-issue trade-offs." },
    { k: "poll", poll: "s3-p25", note: "Use the answers to calibrate the depth: a room with no auction experience needs the mechanics; an experienced room needs the misuse cases." },
    { k: "table", h: "The auction formats", t: [["Format", "Mechanics", "Best for"], ["English reverse", "Bid down; lowest wins at close", "Leverage, 4+ suppliers, fixed spec"], ["Dutch reverse (Coupa)", "Price starts low and rises; first to accept wins", "Speed, simple bundles, testing the floor"], ["Reverse Japanese", "Price falls by steps; accept each step; last active wins", "Incumbent-heavy markets"], ["Sealed bid", "One blind bid each, opened together", "Relationships that must survive"], ["Multi-attribute", "Formula re-ranks price and attributes live", "Quality scored first; confirm in tenant"]], note: "The first three are documented by Coupa. Multi-attribute live auctions are not clearly documented in core Coupa Sourcing." },
    { k: "cards", h: "English reverse auction", c: [["Mechanics", "Suppliers bid down; the lowest bid at close wins"], ["Coupa rules", "No price increases, no very small improvements"], ["Feedback", "Rank or difference to best bid, at the buyer's choice"], ["Watch out", "Full price visibility fuels price wars: show rank (Jap 2007)"]], note: "Closing rules: the literature describes hard close vs soft close with extensions of a few minutes. Coupa's extension parameters must be confirmed in your tenant." },
    { k: "quote", q: "A buyer-controlled clock auction. The buyer sets a low starting price, which rises over time by a pre-set amount. The first supplier to accept the call-out price wins.", by: "Coupa supplier documentation, Dutch reverse auction", note: "Many web sources describe a Dutch auction as a falling price: that is the selling version. In Coupa the reverse Dutch auction rises, bidding is on total cost and all items are awarded together. It needs a well-researched start price: too low and nobody accepts, too high and you overpay." },
    { k: "cards", h: "Reverse Japanese auction", c: [["Start", "Above the expected buying price"], ["Steps", "The price falls; suppliers must accept each step to stay in"], ["Win", "The last active bidder wins"], ["Use", "Incumbent-heavy markets; less visible price-war emotion"]], note: "Practitioners use it with roughly five to eight suppliers (indicative). Exit points are revealed, which can ease tacit coordination in concentrated markets." },
    { k: "poll", poll: "s3-p24", note: "Correct answer: starts low and rises. Repeat the definition once more if more than a few chose the first option." },
    { k: "two", h: "Open or sealed? What Jap found", l: { t: "Open bid (visible price)", b: ["Live price pressure", "Raises supplier suspicion of opportunism", "Erodes cooperation if overused"] }, r: { t: "Sealed bid", b: ["No live price discovery", "Less damage to trust", "Buyer savings did not differ between formats"] }, hi: "r", note: "Jap (2003, 2007), study of six auctions, about US$100M of contracts. Auctions used sparingly can be a ‘wake-up call’; overuse damages relationships." },
    { k: "steps", h: "The preconditions checklist", s: [["Precise specification", "Bids can be ranked automatically"], ["4–5+ qualified bidders", "Smeltzer & Carr (2003)"], ["Market with spare capacity", "And an account suppliers want"], ["Price or a formula decides", "Non-price evaluated before the auction"], ["Low switching cost", "And a relationship that tolerates it"], ["Credible BATNA", "And a real intention to award"]], note: "One ‘no’ is enough to stop. This is the slide participants should photograph." },
    { k: "stats", h: "The evidence in numbers", s: [["5–15%", "typical claimed price reductions (Jap 2002; Smeltzer & Carr 2003)"], ["4–5", "qualified bidders as a minimum to start (Smeltzer & Carr 2003)"], ["> 1/3", "of US federal reverse auctions in FY2012 had no interactive bidding (GAO-14-108)"], ["Up to 3%", "of the winning bid charged by the auction provider (GAO)"]], foot: "Academic figures as summarised by Mora Cortez et al. (2023). A range, not a promise.", note: "The GAO lesson: an auction with one bidder is just an expensive RFQ." },
    { k: "quote", q: "The savings actually achieved are less than that reported by suppliers of online auction services.", by: "Emiliani & Stec (2002), Supply Chain Management: An International Journal", note: "Gross price reductions differ from net savings: switching costs, quality problems, internal effort. Report auction results net." },
    { k: "quote", q: "Auctions perform poorly when projects are complex, contractual design is incomplete and there are few bidders.", by: "Bajari, McMillan & Tadelis (2009), on private building contracts", note: "They also found that auctions stifle the buyer-supplier communication needed to use the contractor's expertise. That is the case for negotiation in complex services." },
    { k: "cards", h: "EU Directive 2014/24 Art. 35 as reference practice", c: [["Precise specification", "Public e-auctions require precisely established specifications"], ["Evaluate first", "Non-price elements fully evaluated before the auction starts"], ["Disclose the formula", "The mathematical re-ranking formula is published"], ["Excluded", "Services with intellectual performances as their subject, such as design"]], note: "A public-law rule, but an excellent heuristic for a private insurer: creative agencies and consulting fail the test." },
    { k: "cards", h: "Misuse cases", c: [["Intellectual services", "Consulting, creative, IT development cannot be ranked automatically"], ["Price-only labour services", "Cleaning or security bids below sustainable wages"], ["One or two bidders", "No competition, only a fee"], ["Auction as a bluff", "No intention to award, or rules hidden"], ["Overuse with partners", "Liker & Choi (2004) on the US automakers' supplier relations"]], note: "The US auto example: Ford's reverse auctions and GM's switch-at-any-moment contracts left relations worse than before the 1980s quality movement (Liker & Choi, HBR 2004)." },
    { k: "example", h: "The best case: aggregated commodities", tag: "Public example (UK)", b: ["34 councils aggregated about 48,000 IT devices under a CCS framework", "Further competition concluded by an e-auction", "£8.8M saved over two years against a pre-auction value of £24.6M (about 36%)", "Savings per basket ranged from 2% to 44%", "Best-case conditions: do not transfer these percentages to services"], note: "Published GOV.UK case study, 2016, since withdrawn as older than five years. It shows what aggregation plus auction can do for commodities." },
    { k: "table", h: "Rules to publish before any auction", t: [["Rule", "Decide and publish"], ["Start or reserve price", "Based on should-cost or benchmark"], ["Decrement", "Minimum improvement per bid (confirm the setting in your tenant)"], ["Closing", "Hard close or extensions (confirm in your tenant)"], ["Feedback", "Rank or difference to best bid"], ["Award rule", "Is the best bid guaranteed to win? On which formula?"]], note: "Procedural fairness reduces perceived opportunism (Daly & Nath 2005, via Mora Cortez et al.). Offer a mock auction to every supplier." },
    { k: "cards", h: "Auction ethics", c: [["No phantom bidders", "Never fake competition"], ["No bluff", "Run an auction only if you will award as announced"], ["No post-auction haggling", "The auction result is the price"], ["Codes of conduct", "Transparency, security, confidentiality, auditing (Emiliani 2005)"]], note: "Suppliers talk to each other. One unethical auction makes the next ten harder." },
    { k: "table", h: "Suitability: four Nordvia categories", t: [["Category", "Verdict", "Why"], ["P5 Office supplies and print", "English reverse after RFQ", "Precise items, many suppliers, price decides"], ["P1 Office cleaning", "No price-only auction", "Labour-intensive; quality first; few strong bidders"], ["P7 Creative agencies", "No auction", "Intellectual services (Art. 35 logic)"], ["P4 Network and telecom", "Possible on standard tariffs, with care", "Only with 4+ qualified providers and the DORA assessment done"]], foot: "Fictional case.", note: "Telmo is deliberately open: claims systems use it, so it may support a critical function. Let the rooms argue it in the practice." },
    { k: "exercise", h: "Auction suitability check", min: 15, where: "Practice 3.4 in your workbook", b: ["Check P5, P1, P7 and P4 against the preconditions", "Add your own project as row five", "Choose a format or write ‘no auction’", "If you chose an auction: write the rules you would publish"], note: "Insist on the number of qualified bidders as a number, not ‘several’." },
    { k: "debrief", h: "Debrief", b: ["Where did the rooms disagree, and on which precondition?", "Who chose an auction for their own project? Defend it", "Would an auction between B and D in the cleaning case help?", "Which format would your incumbent hate most, and why?"], note: "The cleaning answer: no. Two strong bidders, labour-intensive service, relationship needed. A BAFO does the job." },
    { k: "takeaways", h: "3.4 in three lines", b: ["Auctions work for precise specifications, enough bidders and price-led decisions", "Expect 5–15% at best and report savings net (Jap; Emiliani & Stec)", "Know Coupa's formats: English reverse, Dutch reverse rising from low, reverse Japanese"], note: "Bridge to 3.5: now we put all of this into a Coupa event." },

    // ---------- 3.5 ----------
    { k: "section", n: "3.5", h: "Coupa Sourcing in practice", sub: "Where the event lives: invitations, Q&A, bids, scoring, award and audit trail." },
    { k: "statement", h: "Use what Coupa documents with confidence. Confirm the rest before you promise it.", p: "A supplier briefing that promises a setting your tenant does not have is a credibility problem.", note: "Coupa's documentation moved (compass.coupa.com is legacy, docs.coupa.com current). The public pages describe the supplier side best." },
    { k: "table", h: "Coupa event types", t: [["Event", "What it is for"], ["Spot Buy", "Urgent or short-term needs, no contract"], ["RFI", "Qualitative information, forms and attachments, no pricing"], ["RFQ", "Prices for items and lots"], ["RFP", "Prices plus information in the same event"], ["Auction", "Stand-alone or after an RFx as pre-bidding phase"]], note: "These are the event types in Coupa's supplier documentation. Map each of the 3.1 sequences onto them." },
    { k: "flow", h: "An event's life in Coupa", s: ["Template", "Items, lots, questionnaires", "Invite (Private)", "Q&A in Message Center", "Bids / pre-bidding", "Scoring", "Award", "CLM contract"], note: "Privacy options are Public, Private (invited suppliers only, the usual choice) and Hidden. Suppliers respond through the Coupa Supplier Portal and accept the event terms before access; that ‘Yes’ cannot be reversed. Mention it in the supplier briefing." },
    { k: "cards", h: "The pre-bidding phase", c: [["What it is", "The RFx serves as the pre-bidding phase of an auction"], ["Updates", "Suppliers can update their submission without limit"], ["Rules", "Bidding rules do not apply yet"], ["Feedback", "Submissions are collected without feedback"]], note: "This is where quality is evaluated and bidders qualified before any auction, as Art. 35 practice requires." },
    { k: "cards", h: "Questionnaires, lots and items", c: [["Questionnaires", "Several per event: knock-out, quality, regulatory (DORA, InfoSec)"], ["Lots", "Items in a lot are always awarded together and ranked together"], ["Participation", "Partial participation where configured"], ["Excel", "Bulk import and export of supplier responses"]], note: "Build the knock-out questionnaire first; a failed gate should stop the bidder before anyone reads the quality answers." },
    { k: "two", h: "Settings: documented vs confirm in your tenant", l: { t: "Documented by Coupa", b: ["English reverse, Dutch reverse, reverse Japanese", "Rank or difference-to-best feedback", "No increases or very small improvements", "Pre-bidding without feedback", "Lots awarded together"] }, r: { t: "Confirm in your Coupa tenant", b: ["Overtime / soft-close extensions", "Minimum decrement parameters", "Sealed-envelope opening", "Multi-attribute live auctions", "Weighted scoring set-up in core Sourcing"] }, hi: "r", note: "Do not present the right-hand column as fact. Agree with your Coupa administrator how each is handled, and write it in the set-up sheet." },
    { k: "cards", h: "Scoring in practice", c: [["Confirm first", "How weighted scoring is configured and who sees which scores"], ["Fallback", "Run the published model in the evaluation template, attached to the event"], ["Keep prices apart", "By role or by stage, if no sealed-envelope setting exists"], ["Record", "Scores and rationale stored with the event"]], note: "Third parties describe weights × scores in Coupa; the exact core configuration is not verified in Coupa's public docs. Treat it as a tenant question." },
    { k: "cards", h: "Coupa Sourcing Optimization", c: [["Origin", "Ex-Trade Extensions, acquired by Coupa in May 2017"], ["Expressive bidding", "Packages, bundles, volume discounts, alternatives"], ["Scenarios", "What-if award comparisons under constraints"], ["Rounds", "Several rounds, award flowing to contracts and catalogues"]], note: "Vendor descriptions; Coupa's case savings figures are vendor claims. Indirect uses: multi-site FM, telecom lines, hotel programmes, print, courier, temp staffing by region." },
    { k: "example", h: "Optimisation for Nordvia cleaning", tag: "Worked example (fictional)", b: ["Three sites, two countries, four to six bidders", "Bidders price each lot and any bundle they like", "Constraint: at least one supplier per country with local capacity", "Scenario 1: best per lot · Scenario 2: lowest total · Scenario 3: max two suppliers", "The buyer compares cost against risk before choosing"], note: "With three sites a spreadsheet can do it; with thirty sites across entities, optimisation earns its place. That is the Group-level case." },
    { k: "table", h: "Coupa's role by negotiation type", t: [["Negotiation type", "Coupa tool"], ["Price-only, many suppliers", "RFQ + English reverse auction"], ["Few suppliers, incumbent-heavy", "Reverse Japanese or sealed BAFO"], ["Quality-led services", "RFP + negotiation rounds + BAFO (follow-on events)"], ["Panel call-offs", "Mini-competition as an RFP event to panel members"], ["Multi-lot with bundles", "Sourcing Optimization"], ["Sole source", "Data preparation and CLM workflow, not competition"]], note: "Session 4 deepens this matrix. Here the point is that the Message Center and audit trail serve every type." },
    { k: "flow", h: "From award to buying channel", s: ["Award", "Contract in CLM", "Clause library and approvals", "Supplier onboarded in SIM", "Catalogue or contract-backed buying", "Invoices matched to contract"], note: "Coupa describes winning terms flowing into draft contracts and catalogues (vendor description). Session 4 covers the handover in depth." },
    { k: "cards", h: "Good practice: templates and audit trail", c: [["Templates by route", "Soft-FM tender, panel mini-competition, RFQ plus auction"], ["Everything in the event", "Draft contract, weights, annexes; not in emails"], ["Message Center only", "Every clarification logged"], ["Regulatory questions", "DORA and outsourcing questionnaires reused from SIM"]], note: "Templates turn good practice into the default. Ask who owns the templates in your team today." },
    { k: "example", h: "Set-up sheet: Nordvia P1 cleaning", tag: "Worked example (fictional)", b: ["Event: RFP, Private, three lots, bundle option", "Questionnaires: knock-out (wage compliance, insurance), quality, ESG", "Attachments: hybrid specification, staff data, draft contract with KPIs", "Scoring: 50/50, relative price formula, quality scored without prices", "Follow-on: BAFO event to the best two; no auction"], note: "This is the model answer for the practice. Ask what they would confirm in the tenant: scoring set-up and how prices are kept from quality evaluators." },
    { k: "poll", poll: "s3-p26", note: "Use the result to decide where to spend the last minutes of 3.5 and the case debrief." },
    { k: "exercise", h: "Your Coupa event set-up sheet", min: 15, where: "Practice 3.5 in your workbook", b: ["Fill the ten lines of the set-up sheet", "Mark each setting you must confirm in your tenant", "Write who will build the event and who approves it", "Swap with a neighbour: could they build it from your sheet?"], note: "The neighbour test is the quality check: if a colleague cannot build the event from the sheet, it is not finished." },
    { k: "debrief", h: "Debrief", b: ["Which settings did you mark ‘confirm in tenant’?", "Who needs Sourcing Optimization, and who only thinks so?", "Where will your draft contract and weights live?", "What will you ask your Coupa administrator this week?"], note: "Collect the list of tenant questions for the whole cohort and send it to the Coupa administrator after the session." },
    { k: "takeaways", h: "3.5 in three lines", b: ["Coupa documents event types, auction formats, pre-bidding, lots and feedback: use them", "Confirm overtime, decrements, sealed opening and scoring in your tenant", "Put everything in the event, and close the loop to CLM and catalogues"], note: "Bridge to the case: now the whole chain on one lot." },

    // ---------- Case 3 ----------
    { k: "section", n: "Case 3", h: "The HQ cleaning lot, end to end", sub: "Nordvia Facilities, a fictional case" },
    { k: "example", h: "The situation", tag: "Case 3 · Nordvia (fictional)", b: ["Office cleaning, €2.4M, 3 sites in 2 countries, rolled over since 2019", "Quality complaints at HQ; the Head of Real Estate wants a decision this month", "RFP issued with hybrid specification, 3 + 1 + 1 term, published 50/50 model", "Four bids for the HQ lot: A incumbent, B, C, D", "C looks abnormally low; D requires a 4-year term"], note: "Remind teams that the numbers are the ones from 3.3. The case is about decisions, not arithmetic." },
    { k: "exercise", h: "Your team's answer", min: 25, where: "Case tab in your workbook", b: ["How do you handle Bidder C?", "Whom do you negotiate with, or ask for a BAFO?", "Auction or not, and why?", "How do you treat D's 4-year term condition?", "Your award recommendation and its conditions"], note: "Teams often want to auction B and D. Let them argue it; challenge with the preconditions in the debrief." },
    { k: "debrief", h: "Debrief", b: ["Who would auction, and which precondition fails?", "Who accepted D's 4-year term, and is that fair to B?", "How did you write the sensitivity into the recommendation?", "What would you design differently next time (a quality threshold)?"], note: "A published quality threshold of 60 would have excluded C automatically. That is the design lesson for Fieldwork 3." },
    { k: "cards", h: "One strong answer", c: [["Bidder C", "Written request to explain hours and price; reject and record if it fails"], ["Next step", "BAFO with B and D on the published 50/50 model; no auction"], ["D's term", "D prices the compliant 3 + 1 + 1; no structure change for one bidder"], ["Recommendation", "Best BAFO score, subject to due diligence; state that the decision is close"]], note: "Present only after the teams. There is more than one good answer; the logic is fairness, published rules and honesty about sensitivity." },

    // ---------- Close ----------
    { k: "section", n: "Close", h: "Fieldwork 3 and next steps", sub: "Validate the weights before anyone sees a bid." },
    { k: "steps", h: "Fieldwork 3, before Session 4", s: [["RFx pack outline", "Instructions, specification, lots, pricing, questionnaire, contract, annexes"], ["Weights validated", "With the business owner, before issue, recorded"], ["Test bid sets", "Three fictional sets through your model"], ["Tenant settings", "Confirmed with your Coupa administrator"], ["Regulatory gates", "Agreed with Risk or Compliance where triage flagged it"]], note: "The validated evaluation model is the core of Sourcing Case part 3. Session 4 builds the negotiation plan on top of it." },
    { k: "two", h: "The weights conversation with the business owner", l: { t: "Ask", b: ["‘If the bids come in close, these weights decide. Are you comfortable?’", "‘What would make you unhappy with the winner?’", "‘Which criterion would you never trade?’"] }, r: { t: "Show", b: ["A test bid set where the ranking flips", "The knock-out gates that are not negotiable", "Where the model will live in Coupa"] }, note: "A business owner who sees the model reverse a ranking understands why the weights must be agreed before issue." },
    { k: "takeaways", h: "Session 3 in five lines", b: ["The tool follows the strategy: choose the question, then the event", "Design the request so bids are comparable; fix the model before issue", "Run it fairly: one channel, individual scores, consensus, sensitivity", "Auction only when the preconditions hold, in the right format", "Build it in Coupa, and confirm what your tenant really does"], note: "Ask each participant to write the one line they will apply first in their own project." },
    { k: "statement", h: "Next session: HOW do we close it well?", p: "Bring your RFx plan, your validated evaluation model and your e-negotiation design. We will negotiate, contract and hand over.", note: "Session 4 opens with the Kelvar sole-source negotiation role-play. Ask participants to reread the Kelvar data before then." }
  ]
};
